       });
+      expect(options?.onSuccess).toEqual(expect.any(Function));
+    });
+
+    test('SFCC-250 step 4.2: calls capBasketQuantities with the merged basket once the merge mutation succeeds, and not before', () => {
+      const { result, rerender } = renderHook(() => useWishlistAuthDrawer({ intentId: TEST_INTENT_ID }), {
