+      });
+
+      act(() => {
+        result.current.handleTriggerClick(makeSyntheticEvent());
+      });
+
+      mockRegistered();
+      rerender();
+
+      expect(mockMergeBasketMutate).toHaveBeenCalledTimes(1);
+      expect(mockCapBasketQuantities).not.toHaveBeenCalled();
+
+      // Simulate React Query invoking the merge mutation's onSuccess callback with the
