import { describe, test, expect, vi, beforeEach } from 'vitest';
import { act } from '@testing-library/react';
import { useQueryClient, type QueryClient } from '@tanstack/react-query';
import type { ShopperBasketsV2Types } from 'commerce-sdk-isomorphic';
import { renderHookWithQueryClient } from 'app/test-utils/renderWithProviders';
import { useCartMergeAndCap, type CartCapBasket } from './useCartMergeAndCap';

// Hoisted so the vi.mock factory below (hoisted above these imports by Vitest) can reference it —
// a plain `const` here would not yet be initialised at that point.
const { mockMutateAsync } = vi.hoisted(() => ({
  mockMutateAsync: vi.fn(),
}));

vi.mock('@salesforce/commerce-sdk-react', () => ({
  useShopperBasketsV2Mutation: () => ({ mutateAsync: mockMutateAsync }),
}));

// REWORK (round 1, SFCC-250 step 4.2): `@tanstack/react-query` is NOT mocked here any more. The
// mutation-in-flight guard used to read a React-render-time `useIsMutating()` snapshot (faked via
// a `mockUseIsMutating` hoisted mock in the original build of this test) — fixed to instead read
// `queryClient.isMutating()` live, inside `capBasketQuantities` itself, at the moment it actually
// runs (see `useCartMergeAndCap.ts`'s own comment on why). There is nothing left to fake:
// `useQueryClient`/`QueryClient`/`QueryClientProvider` were already real (previously via
// `importOriginal`, for the same reason the loop guard's `getQueryData`/`setQueryData` calls need
// a real cache), and the "mutation-in-flight guard" tests below now seed the real mutation cache
// directly instead of a mocked hook return value — exactly the "a real concurrent mutation starts
// elsewhere" shape the fix exists for.

const makeLineItem = (
  overrides: Partial<ShopperBasketsV2Types.BasketProductItem> = {},
): ShopperBasketsV2Types.BasketProductItem => ({
  itemId: 'item-1',
  productId: 'product-1',
  quantity: 1,
  ...overrides,
});

const makeBasket = (
  productItems: ShopperBasketsV2Types.BasketProductItem[],
  overrides: Partial<CartCapBasket> = {},
): CartCapBasket => ({
  basketId: 'basket-1',
  lastModified: '2026-09-20T00:00:00.000Z',
  productItems,
  ...overrides,
});

// A short real macrotask flush — guaranteed to run after every currently-queued microtask
// (unlike a fixed number of `await Promise.resolve()` hops, which is easy to get wrong), so a
// test can observe "capBasketQuantities has started its own write and is now waiting on it"
// without yet resolving that write.
const flushMicrotasks = () => new Promise((resolve) => setTimeout(resolve, 0));

/**
 * Starts a real, live in-flight mutation directly on the given QueryClient's own mutation
 * cache — bypassing React and any hook subscription entirely, the same way `useMutation().
 * mutate()` does internally (`MutationObserver` calls `mutationCache.build(client, options)`
 * then `.execute()` — confirmed against `node_modules/@tanstack/query-core/build/lib/
 * mutationCache.esm.js` and `mutation.esm.js`). Invoked directly here so nothing about it
 * depends on, or triggers, a React render — matching a real concurrent mutation happening
 * somewhere else in the app that a given hook instance has no subscription to. `execute()` is
 * deliberately not awaited: its `mutationFn` never resolves, and the synchronous portion of
 * `execute()` (up to its first internal `await`) already dispatches the `'loading'` status
 * before this function returns control, which is all `queryClient.isMutating()` needs to see it.
 * Call `.destroy()` on the returned mutation once a test is done asserting, to clear its pending
 * 5-minute GC timer (`Removable.scheduleGc`, `.../query-core/build/lib/removable.esm.js`) rather
 * than leaving a real dangling timer behind after the test ends.
 */
const seedInFlightMutation = (queryClient: QueryClient) => {
  const mutation = queryClient.getMutationCache().build(queryClient, {
    mutationFn: () => new Promise<never>(() => {}),
  });
  void mutation.execute();
  return mutation;
};

describe('useCartMergeAndCap', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockMutateAsync.mockResolvedValue({});
  });

  describe("quantity boundary — fallback max of 3 (SFCC-268 not deployed, per this step's own pass criterion 6)", () => {
    test('line at 2: no change, no write', async () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([makeLineItem({ quantity: 2 })]);

      const outcome = await act(async () => result.current.capBasketQuantities(basket));

      expect(outcome).toEqual({ status: 'not-needed' });
      expect(mockMutateAsync).not.toHaveBeenCalled();
    });

    test('line at 3: no change — the >= boundary is 4, not 3 (== would wrongly leave 4 unreduced, not this case)', async () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([makeLineItem({ quantity: 3 })]);

      const outcome = await act(async () => result.current.capBasketQuantities(basket));

      expect(outcome).toEqual({ status: 'not-needed' });
      expect(mockMutateAsync).not.toHaveBeenCalled();
    });

    test('line at 4: reduced to 3', async () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([makeLineItem({ itemId: 'a', productId: 'p-a', quantity: 4 })]);

      const outcome = await act(async () => result.current.capBasketQuantities(basket));

      expect(outcome).toEqual({ status: 'corrected' });
      expect(mockMutateAsync).toHaveBeenCalledTimes(1);
      expect(mockMutateAsync).toHaveBeenCalledWith({
        parameters: { basketId: 'basket-1' },
        body: [{ itemId: 'a', productId: 'p-a', quantity: 3 }],
      });
    });

    test('line at 5: reduced to 3, not to 4 — proves the check is a range (> max), not equality against max + 1', async () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([makeLineItem({ itemId: 'a', productId: 'p-a', quantity: 5 })]);

      const outcome = await act(async () => result.current.capBasketQuantities(basket));

      expect(outcome).toEqual({ status: 'corrected' });
      expect(mockMutateAsync).toHaveBeenCalledWith({
        parameters: { basketId: 'basket-1' },
        body: [{ itemId: 'a', productId: 'p-a', quantity: 3 }],
      });
    });

    test('two same-SKU lines already sum_quantities-merged into one line at 4: capped to one line at 3', async () => {
      // sum_quantities merging (step 4.1, useWishlistAuthDrawer.ts) already consolidates two
      // same-SKU lines server-side before this function ever sees the basket — this proves this
      // function correctly caps the already-merged single line, not that it performs
      // consolidation itself (this function never sees two separate same-SKU lines).
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([makeLineItem({ itemId: 'merged', productId: 'p-merged', quantity: 2 + 2 })]);

      const outcome = await act(async () => result.current.capBasketQuantities(basket));

      expect(outcome).toEqual({ status: 'corrected' });
      expect(mockMutateAsync).toHaveBeenCalledTimes(1);
      expect(mockMutateAsync).toHaveBeenCalledWith({
        parameters: { basketId: 'basket-1' },
        body: [{ itemId: 'merged', productId: 'p-merged', quantity: 3 }],
      });
    });

    test('a compliant product carrying a real c_maxOrderQuantity is capped to that value, not the fallback', async () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([makeLineItem({ quantity: 8, c_maxOrderQuantity: 5 } as never)]);

      const outcome = await act(async () => result.current.capBasketQuantities(basket));

      expect(outcome).toEqual({ status: 'corrected' });
      expect(mockMutateAsync).toHaveBeenCalledWith(
        expect.objectContaining({ body: [expect.objectContaining({ quantity: 5 })] }),
      );
    });
  });

  describe('mutation-in-flight guard — reads the live QueryClient state, not a render-time snapshot', () => {
    test('a mutation already in flight when the guard is checked (after an intervening re-render): returns skipped without issuing a write', async () => {
      const { result, rerender } = renderHookWithQueryClient(() => ({
        cap: useCartMergeAndCap(),
        queryClient: useQueryClient(),
      }));

      const inFlight = seedInFlightMutation(result.current.queryClient);
      rerender(); // an intervening re-render — the case this guard has always correctly caught
      expect(result.current.queryClient.isMutating()).toBe(1); // sanity check on the seed itself

      const basket = makeBasket([makeLineItem({ quantity: 5 })]);
      const outcome = await act(async () => result.current.cap.capBasketQuantities(basket));

      expect(outcome).toEqual({ status: 'skipped', reason: 'mutation-in-flight' });
      expect(mockMutateAsync).not.toHaveBeenCalled();
      inFlight.destroy();
    });

    // REWORK (round 1) — reproduces the Tester's confirmed defect directly. `capBasketQuantities`
    // is captured once at render time (exactly like `useWishlistAuthDrawer.ts`'s own top-level
    // `const {capBasketQuantities} = useCartMergeAndCap();`) while nothing is mutating, then a
    // real mutation starts — built directly on the cache, not through a React hook, so nothing
    // causes this hook instance to re-render — before the captured function is actually invoked.
    // This is exactly the async-gap shape `useWishlistAuthDrawer.ts` has between its own render
    // and its later, async `mergeBasket.mutate(...).onSuccess` invocation: nothing guarantees
    // that hook re-renders between capturing `capBasketQuantities` and invoking it. Before the
    // fix (a React-render-time `useIsMutating()` snapshot closed over by `capBasketQuantities`)
    // this returned `{status: 'corrected'}`, because the closure held a value frozen at the
    // render that produced it. Reading `queryClient.isMutating()` live, inside the function
    // body, at the moment it actually runs, is what makes this pass.
    test('a mutation that starts AFTER capBasketQuantities was captured, with no re-render in between, is still caught', async () => {
      const { result } = renderHookWithQueryClient(() => ({
        cap: useCartMergeAndCap(),
        queryClient: useQueryClient(),
      }));

      // Captured while nothing is mutating — deliberately held in plain locals, never re-read
      // from `result.current` again below, so this reproduces the real bug shape regardless of
      // whatever React itself does or doesn't re-render internally in response to the mutation
      // seeded next.
      const { capBasketQuantities } = result.current.cap;
      const { queryClient } = result.current;
      expect(queryClient.isMutating()).toBe(0);

      const inFlight = seedInFlightMutation(queryClient);
      expect(queryClient.isMutating()).toBe(1);

      const basket = makeBasket([makeLineItem({ quantity: 5 })]);
      const outcome = await act(async () => capBasketQuantities(basket));

      expect(outcome).toEqual({ status: 'skipped', reason: 'mutation-in-flight' });
      expect(mockMutateAsync).not.toHaveBeenCalled();
      inFlight.destroy();
    });
  });

  describe('loop guard — one attempt per basket version, no retry storm', () => {
    test('two consecutive invocations against the same basket version issue exactly one write', async () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([makeLineItem({ quantity: 5 })]);

      const first = await act(async () => result.current.capBasketQuantities(basket));
      const second = await act(async () => result.current.capBasketQuantities(basket));

      expect(first).toEqual({ status: 'corrected' });
      expect(second).toEqual({ status: 'skipped', reason: 'already-attempted-this-version' });
      expect(mockMutateAsync).toHaveBeenCalledTimes(1);
    });

    test('a server rejection surfaces an error and a later call against the same unchanged basket does not retry', async () => {
      mockMutateAsync.mockRejectedValueOnce(new Error('server rejected the quantity update'));
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([makeLineItem({ quantity: 5 })]);

      const first = await act(async () => result.current.capBasketQuantities(basket));
      expect(first.status).toBe('error');
      if (first.status === 'error') {
        expect(first.error).toBeInstanceOf(Error);
      }
      expect(mockMutateAsync).toHaveBeenCalledTimes(1);

      const second = await act(async () => result.current.capBasketQuantities(basket));
      expect(second).toEqual({ status: 'skipped', reason: 'already-attempted-this-version' });
      // Still one — the rejection above did not trigger a retry, and the second call did not
      // either.
      expect(mockMutateAsync).toHaveBeenCalledTimes(1);
    });

    test('a genuinely new basket version (e.g. after a real correction changes lastModified) is free to attempt again', async () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const staleBasket = makeBasket([makeLineItem({ quantity: 5 })], { lastModified: 'v1' });
      const newerBasket = makeBasket([makeLineItem({ quantity: 5 })], { lastModified: 'v2' });

      await act(async () => result.current.capBasketQuantities(staleBasket));
      const second = await act(async () => result.current.capBasketQuantities(newerBasket));

      expect(second).toEqual({ status: 'corrected' });
      expect(mockMutateAsync).toHaveBeenCalledTimes(2);
    });
  });

  describe('sequencing — resolves only once its own write settles', () => {
    test('a caller sequencing merge -> cap -> a resume stand-in observes merge, then cap, then resume, in that order', async () => {
      let resolveWrite: (value: unknown) => void = () => {};
      mockMutateAsync.mockImplementation(() => new Promise((resolve) => (resolveWrite = resolve)));

      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([makeLineItem({ quantity: 5 })]);

      const order: string[] = [];
      // Neither of these represents production code from another step — both are local test
      // fixtures standing in for the real merge call (already built, step 4.1) and the real
      // wishlist-resume (not yet built, step 4.4). This test proves a property of
      // `capBasketQuantities` itself: that it does not resolve before its own internal write
      // settles, which is what lets a real caller sequence these three correctly.
      const merge = async () => {
        order.push('merge:start');
        await Promise.resolve();
        order.push('merge:end');
      };
      const resumeStandIn = async () => {
        order.push('resume:start');
        await Promise.resolve();
        order.push('resume:end');
      };

      const sequence = (async () => {
        await merge();
        order.push('merge:resolved');
        const capPromise = result.current.capBasketQuantities(basket);
        order.push('cap:called');
        await capPromise;
        order.push('cap:resolved');
        await resumeStandIn();
        order.push('resume:resolved');
      })();

      // At this point capBasketQuantities has been called and its own write is in flight
      // (mockMutateAsync was invoked) but deliberately not yet resolved.
      await act(async () => {
        await flushMicrotasks();
      });
      order.push('write:in-flight-check');
      expect(mockMutateAsync).toHaveBeenCalledTimes(1);
      expect(order).toEqual(['merge:start', 'merge:end', 'merge:resolved', 'cap:called', 'write:in-flight-check']);

      resolveWrite({});
      await act(async () => {
        await sequence;
      });

      expect(order).toEqual([
        'merge:start',
        'merge:end',
        'merge:resolved',
        'cap:called',
        'write:in-flight-check',
        'cap:resolved',
        'resume:start',
        'resume:end',
        'resume:resolved',
      ]);
    });
  });

  describe('missing basketId', () => {
    test('surfaces an error instead of silently doing nothing or throwing', async () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([makeLineItem({ quantity: 5 })], { basketId: undefined });

      const outcome = await act(async () => result.current.capBasketQuantities(basket));

      expect(outcome.status).toBe('error');
      expect(mockMutateAsync).not.toHaveBeenCalled();
    });
  });
});

